  j constant jsonb := $j$[
{"id":"d5a22d35-89cf-4b1a-a2ae-ddb9a3f0192d","recipe_group_id":"dfcbd159-5bb3-4f73-af00-8afb13e5c9b1","language":"es","slug":"pad-thai-tailandia","public_path":"/pad-thai-tailandia","source_url":"https://manualdecocina.com/pad-thai-tailandia/","title":"Pad Thai con camarones","excerpt":"Pad Thai casero con fideos de arroz, camarones, huevo y salsa de tamarindo, salteado en wok en 10 minutos. Rinde 4 porciones.","summary":"El pad thai es un salteado tailandés de fideos de arroz planos con camarones, huevo, brotes de soja y una salsa agridulce de tamarindo, salsa de pescado y azúcar de palma. Los fideos se remojan 30 minutos en agua templada, sin hervirlos.\n\nLa cocción en wok a fuego fuerte dura unos 10 minutos. Se sirve con cacahuetes tostados, lima y chile en hojuelas. Rinde 4 porciones.","category":"Platos principales","difficulty":"Media","course":"Plato principal","cuisine":"Tailandesa","prep_time_minutes":45,"cook_time_minutes":10,"total_time_minutes":55,"servings":4,"keywords":["pad thai","pad thai con camarones","receta de pad thai","pad thai casero","fideos de arroz salteados","salsa de tamarindo","comida tailandesa"],"ingredients":[{"name":"fideos de arroz planos (5 mm)","amount":"200","unit":"g","group":"Para el salteado"},{"name":"camarones pelados","amount":"250","unit":"g","group":"Para el salteado"},{"name":"ajo, picado","amount":"3","unit":"dientes","group":"Para el salteado"},{"name":"chalota, picada","amount":"1","unit":"unidad","group":"Para el salteado"},{"name":"aceite vegetal","amount":"45","unit":"ml","group":"Para el salteado"},{"name":"huevos","amount":"2","unit":"unidad","group":"Para el salteado"},{"name":"brotes de soja","amount":"150","unit":"g","group":"Para el salteado"},{"name":"cebollines, en trozos de 4 cm","amount":"4","unit":"unidad","group":"Para el salteado"},{"name":"pasta de tamarindo","amount":"3","unit":"cucharada","group":"Para la salsa"},{"name":"salsa de pescado","amount":"45","unit":"ml","group":"Para la salsa"},{"name":"azúcar de palma (o azúcar moreno)","amount":"2","unit":"cucharada","group":"Para la salsa"},{"name":"agua","amount":"45","unit":"ml","group":"Para la salsa"},{"name":"cacahuetes tostados, troceados","amount":"40","unit":"g","group":"Para servir"},{"name":"lima, en gajos","amount":"1","unit":"unidad","group":"Para servir"},{"name":"chile en hojuelas","amount":"0.5","unit":"cucharadita","group":"Para servir"}],"steps":[{"title":"Remoja los fideos","content":"Remoja 200 g de fideos de arroz planos en agua del grifo templada durante 30 minutos, hasta que doblen sin romperse. Escúrrelos.","image_url":"/recetas/pad-thai-tailandia/paso-01.webp","image_alt":"Pad Thai con camarones: Remoja los fideos"},{"title":"Prepara la salsa","content":"Mezcla 3 cucharadas de pasta de tamarindo, 45 ml de salsa de pescado, 2 cucharadas de azúcar de palma y 45 ml de agua hasta que el azúcar se disuelva.","image_url":"/recetas/pad-thai-tailandia/paso-02.webp","image_alt":"Pad Thai con camarones: Prepara la salsa"},{"title":"Prepara los ingredientes","content":"Pela 250 g de camarones. Pica 3 dientes de ajo y 1 chalota, corta 4 cebollines en trozos de 4 cm y trocea 40 g de cacahuetes tostados.","image_url":"/recetas/pad-thai-tailandia/paso-03.webp","image_alt":"Pad Thai con camarones: Prepara los ingredientes"},{"title":"Saltea los camarones","content":"Calienta un wok a fuego fuerte con 45 ml de aceite. Saltea la chalota y el ajo 20 segundos, añade los camarones y cocínalos 1 minuto y medio, hasta que estén rosados. Apártalos a un lado.","image_url":"/recetas/pad-thai-tailandia/paso-04.webp","image_alt":"Pad Thai con camarones: Saltea los camarones"},{"title":"Cocina el huevo","content":"En el hueco del wok, revuelve 2 huevos durante 30 segundos.","image_url":"/recetas/pad-thai-tailandia/paso-05.webp","image_alt":"Pad Thai con camarones: Cocina el huevo"},{"title":"Añade fideos y salsa","content":"Agrega los fideos escurridos y la salsa. Saltea de 2 a 3 minutos, hasta que absorban la salsa y estén tiernos. Si se secan, añade un chorrito de agua.","image_url":"/recetas/pad-thai-tailandia/paso-06.webp","image_alt":"Pad Thai con camarones: Añade fideos y salsa"},{"title":"Añade los brotes","content":"Fuera del fuego, mezcla durante 30 segundos la mitad de 150 g de brotes de soja y los cebollines.","image_url":"/recetas/pad-thai-tailandia/paso-07.webp","image_alt":"Pad Thai con camarones: Añade los brotes"},{"title":"Sirve","content":"Sirve con los cacahuetes, el resto de los brotes, gajos de lima y ½ cucharadita de chile en hojuelas.","image_url":"/recetas/pad-thai-tailandia/paso-08.webp","image_alt":"Pad Thai con camarones: Sirve"}],"image_url":"/recetas/pad-thai-tailandia/portada.webp","gallery":[{"url":"/recetas/pad-thai-tailandia/portada.webp","alt":"Pad Thai con camarones"}],"notes":"El tiempo de preparación incluye 30 minutos de remojo de los fideos. Deja todos los ingredientes listos antes de encender el fuego: la cocción es muy rápida. Si tu wok es pequeño, cocina en dos tandas para que los fideos se saltéen y no se cuezan al vapor. Contiene cacahuetes, crustáceos, pescado y huevo.","nutrition":{"calories":500,"protein_g":22.5,"carbs_g":61,"fat_g":18.4,"sodium_mg":1192,"serving_size":"1 porción (1/4 de la receta)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Suma de nutrientes por 100 g multiplicados por los pesos de los ingredientes y divididos entre 4 porciones. Se usan 200 g de fideos de arroz secos, 250 g de camarones, 100 g de huevo, 48 g de pasta de tamarindo, 54 g de salsa de pescado (45 ml), 25 g de azúcar, 41 g de aceite (45 ml), 9 g de ajo, 25 g de chalota, 150 g de brotes de soja, 40 g de cebollín y 40 g de cacahuetes.","note":"Estimación por porción. La lima y el chile en hojuelas no se contabilizan. La pasta de tamarindo y el azúcar de palma se calculan con valores de referencia (tamarindo crudo y azúcar moreno). El sodio depende sobre todo de la salsa de pescado.","inputs":[{"fdc_id":"168890","description":"Noodles, rice, dry","grams":200,"per100":{"calories":364,"protein_g":3.44,"carbs_g":80.2,"fat_g":0.56,"saturated_fat_g":0.1,"fiber_g":1.6,"sodium_mg":24}},{"fdc_id":"175179","description":"Crustaceans, shrimp, mixed species, raw","grams":250,"per100":{"calories":85,"protein_g":20.1,"carbs_g":0,"fat_g":0.51,"saturated_fat_g":0.13,"fiber_g":0,"sodium_mg":119}},{"fdc_id":"171287","description":"Egg, whole, raw, fresh","grams":100,"per100":{"calories":143,"protein_g":12.56,"carbs_g":0.72,"fat_g":9.51,"saturated_fat_g":3.13,"fiber_g":0,"sodium_mg":142}},{"fdc_id":"169123","description":"Tamarinds, raw (proxy de la pasta de tamarindo)","grams":48,"per100":{"calories":239,"protein_g":2.8,"carbs_g":62.5,"fat_g":0.6,"saturated_fat_g":0.27,"fiber_g":5.1,"sodium_mg":28}},{"fdc_id":"174535","description":"Sauce, fish, ready-to-serve","grams":54,"per100":{"calories":35,"protein_g":5.06,"carbs_g":3.64,"fat_g":0.01,"saturated_fat_g":0,"fiber_g":0,"sodium_mg":7851}},{"fdc_id":"168833","description":"Sugars, brown (proxy del azúcar de palma)","grams":25,"per100":{"calories":380,"protein_g":0.12,"carbs_g":98.09,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sodium_mg":28}},{"fdc_id":"172336","description":"Oil, soybean, salad or cooking","grams":41,"per100":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":15.65,"fiber_g":0,"sodium_mg":0}},{"fdc_id":"169230","description":"Garlic, raw","grams":9,"per100":{"calories":149,"protein_g":6.36,"carbs_g":33.06,"fat_g":0.5,"saturated_fat_g":0.09,"fiber_g":2.1,"sodium_mg":17}},{"fdc_id":"170499","description":"Shallots, raw","grams":25,"per100":{"calories":72,"protein_g":2.5,"carbs_g":16.8,"fat_g":0.1,"saturated_fat_g":0.02,"fiber_g":3.2,"sodium_mg":12}},{"fdc_id":"168412","description":"Mung beans, mature seeds, sprouted, raw","grams":150,"per100":{"calories":30,"protein_g":3.04,"carbs_g":5.94,"fat_g":0.18,"saturated_fat_g":0.04,"fiber_g":1.8,"sodium_mg":6}},{"fdc_id":"170005","description":"Onions, spring or scallions (includes tops and bulb), raw","grams":40,"per100":{"calories":32,"protein_g":1.83,"carbs_g":7.34,"fat_g":0.19,"saturated_fat_g":0.03,"fiber_g":2.6,"sodium_mg":16}},{"fdc_id":"172430","description":"Peanuts, all types, dry-roasted, without salt","grams":40,"per100":{"calories":587,"protein_g":24.35,"carbs_g":21.51,"fat_g":49.66,"saturated_fat_g":6.89,"fiber_g":8,"sodium_mg":6}}]},"seo":{"title":"Pad Thai con camarones casero en 10 minutos | Manual de Cocina","description":"Pad Thai casero con fideos de arroz, camarones, huevo y salsa de tamarindo, salteado en wok en 10 minutos. Receta paso a paso para 4 porciones.","image_variants":["/recetas/pad-thai-tailandia/portada-1x1.webp","/recetas/pad-thai-tailandia/portada-4x3.webp","/recetas/pad-thai-tailandia/portada-16x9.webp"],"faq":[{"q":"¿Qué fideos se usan para el pad thai?","a":"Fideos de arroz planos de unos 5 mm de ancho. Se remojan en agua templada unos 30 minutos y no se hierven."},{"q":"¿Se puede hacer pad thai sin pasta de tamarindo?","a":"Se puede sustituir por jugo de lima con un poco más de azúcar, pero el sabor será menos profundo que con tamarindo."},{"q":"¿Por qué se remojan los fideos en lugar de hervirlos?","a":"Porque terminan de ablandarse en el wok con la salsa. Si se hierven antes, se pasan y se rompen al saltearlos."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"7858d9c1-32e4-506a-a011-da1f6ebdfdd5","recipe_group_id":"dfcbd159-5bb3-4f73-af00-8afb13e5c9b1","language":"de","slug":"pad-thai-selber-machen","public_path":"/de/pad-thai-selber-machen","source_url":null,"title":"Pad Thai mit Garnelen","excerpt":"Pad Thai selber machen mit Reisnudeln, Garnelen, Ei und Tamarindensauce, in 10 Minuten im Wok gebraten. Ergibt 4 Portionen.","summary":"Pad Thai ist ein thailändisches Pfannengericht aus flachen Reisnudeln mit Garnelen, Ei, Sojasprossen und einer süß-sauren Sauce aus Tamarinde, Fischsauce und Palmzucker. Die Nudeln werden 30 Minuten in lauwarmem Wasser eingeweicht, nicht gekocht.\n\nDas Braten im Wok bei starker Hitze dauert etwa 10 Minuten. Serviert wird mit gerösteten Erdnüssen, Limette und Chiliflocken. Ergibt 4 Portionen.","category":"Hauptgerichte","difficulty":"Mittel","course":"Hauptgericht","cuisine":"Thailändisch","prep_time_minutes":45,"cook_time_minutes":10,"total_time_minutes":55,"servings":4,"keywords":["Pad Thai","Pad Thai mit Garnelen","Pad Thai Rezept","Pad Thai selber machen","gebratene Reisnudeln","Tamarindensauce","thailändisches Essen"],"ingredients":[{"name":"flache Reisnudeln (5 mm)","amount":"200","unit":"g","group":"Zum Braten"},{"name":"Garnelen, geschält","amount":"250","unit":"g","group":"Zum Braten"},{"name":"Knoblauch, gehackt","amount":"3","unit":"Zehen","group":"Zum Braten"},{"name":"Schalotte, gehackt","amount":"1","unit":"Stück","group":"Zum Braten"},{"name":"Pflanzenöl","amount":"45","unit":"ml","group":"Zum Braten"},{"name":"Eier","amount":"2","unit":"Stück","group":"Zum Braten"},{"name":"Sojasprossen","amount":"150","unit":"g","group":"Zum Braten"},{"name":"Frühlingszwiebeln, in 4-cm-Stücken","amount":"4","unit":"Stück","group":"Zum Braten"},{"name":"Tamarindenpaste","amount":"3","unit":"Esslöffel","group":"Für die Sauce"},{"name":"Fischsauce","amount":"45","unit":"ml","group":"Für die Sauce"},{"name":"Palmzucker (oder brauner Zucker)","amount":"2","unit":"Esslöffel","group":"Für die Sauce"},{"name":"Wasser","amount":"45","unit":"ml","group":"Für die Sauce"},{"name":"geröstete Erdnüsse, gehackt","amount":"40","unit":"g","group":"Zum Servieren"},{"name":"Limette, in Spalten","amount":"1","unit":"Stück","group":"Zum Servieren"},{"name":"Chiliflocken","amount":"0.5","unit":"Teelöffel","group":"Zum Servieren"}],"steps":[{"title":"Nudeln einweichen","content":"200 g flache Reisnudeln 30 Minuten in lauwarmem Leitungswasser einweichen, bis sie sich biegen lassen, ohne zu brechen. Abtropfen lassen.","image_url":"/recetas/pad-thai-tailandia/paso-01.webp","image_alt":"Pad Thai mit Garnelen: Nudeln einweichen"},{"title":"Sauce anrühren","content":"3 Esslöffel Tamarindenpaste, 45 ml Fischsauce, 2 Esslöffel Palmzucker und 45 ml Wasser verrühren, bis sich der Zucker aufgelöst hat.","image_url":"/recetas/pad-thai-tailandia/paso-02.webp","image_alt":"Pad Thai mit Garnelen: Sauce anrühren"},{"title":"Zutaten vorbereiten","content":"250 g Garnelen schälen. 3 Knoblauchzehen und 1 Schalotte hacken, 4 Frühlingszwiebeln in 4-cm-Stücke schneiden und 40 g geröstete Erdnüsse grob hacken.","image_url":"/recetas/pad-thai-tailandia/paso-03.webp","image_alt":"Pad Thai mit Garnelen: Zutaten vorbereiten"},{"title":"Garnelen braten","content":"Einen Wok bei starker Hitze mit 45 ml Öl erhitzen. Schalotte und Knoblauch 20 Sekunden braten, die Garnelen dazugeben und 1 ½ Minuten braten, bis sie rosa sind. Zur Seite schieben.","image_url":"/recetas/pad-thai-tailandia/paso-04.webp","image_alt":"Pad Thai mit Garnelen: Garnelen braten"},{"title":"Ei braten","content":"In der freien Stelle des Woks 2 Eier 30 Sekunden verrühren.","image_url":"/recetas/pad-thai-tailandia/paso-05.webp","image_alt":"Pad Thai mit Garnelen: Ei braten"},{"title":"Nudeln und Sauce zugeben","content":"Die abgetropften Nudeln und die Sauce zugeben. 2 bis 3 Minuten braten, bis sie die Sauce aufgenommen haben und zart sind. Werden sie trocken, einen Schuss Wasser zugeben.","image_url":"/recetas/pad-thai-tailandia/paso-06.webp","image_alt":"Pad Thai mit Garnelen: Nudeln und Sauce zugeben"},{"title":"Sprossen zugeben","content":"Vom Herd nehmen und die Hälfte von 150 g Sojasprossen sowie die Frühlingszwiebeln 30 Sekunden untermischen.","image_url":"/recetas/pad-thai-tailandia/paso-07.webp","image_alt":"Pad Thai mit Garnelen: Sprossen zugeben"},{"title":"Servieren","content":"Mit den Erdnüssen, den restlichen Sprossen, Limettenspalten und ½ Teelöffel Chiliflocken servieren.","image_url":"/recetas/pad-thai-tailandia/paso-08.webp","image_alt":"Pad Thai mit Garnelen: Servieren"}],"image_url":"/recetas/pad-thai-tailandia/portada.webp","gallery":[{"url":"/recetas/pad-thai-tailandia/portada.webp","alt":"Pad Thai mit Garnelen"}],"notes":"Die Zubereitungszeit enthält 30 Minuten Einweichzeit für die Nudeln. Alle Zutaten bereitstellen, bevor das Feuer angeht: Das Braten geht sehr schnell. Bei einem kleinen Wok in zwei Portionen braten, damit die Nudeln braten und nicht dämpfen. Enthält Erdnüsse, Krebstiere, Fisch und Ei.","nutrition":{"calories":500,"protein_g":22.5,"carbs_g":61,"fat_g":18.4,"sodium_mg":1192,"serving_size":"1 Portion (1/4 des Rezepts)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nährwerte je 100 g, multipliziert mit dem Gewicht der Zutaten und durch 4 Portionen geteilt. Verwendet werden 200 g trockene Reisnudeln, 250 g Garnelen, 100 g Ei, 48 g Tamarindenpaste, 54 g Fischsauce (45 ml), 25 g Zucker, 41 g Öl (45 ml), 9 g Knoblauch, 25 g Schalotte, 150 g Sojasprossen, 40 g Frühlingszwiebel und 40 g Erdnüsse.","note":"Schätzung pro Portion. Limette und Chiliflocken werden nicht eingerechnet. Tamarindenpaste und Palmzucker werden mit Referenzwerten berechnet (rohe Tamarinde und brauner Zucker). Das Natrium stammt vor allem aus der Fischsauce."},"seo":{"title":"Pad Thai mit Garnelen selber machen in 10 Minuten | Manual de Cocina","description":"Pad Thai selber machen mit Reisnudeln, Garnelen, Ei und Tamarindensauce, in 10 Minuten im Wok gebraten. Schritt für Schritt für 4 Portionen.","image_variants":["/recetas/pad-thai-tailandia/portada-1x1.webp","/recetas/pad-thai-tailandia/portada-4x3.webp","/recetas/pad-thai-tailandia/portada-16x9.webp"],"faq":[{"q":"Welche Nudeln braucht man für Pad Thai?","a":"Flache Reisnudeln von etwa 5 mm Breite. Sie werden etwa 30 Minuten in lauwarmem Wasser eingeweicht und nicht gekocht."},{"q":"Geht Pad Thai ohne Tamarindenpaste?","a":"Man kann sie durch Limettensaft mit etwas mehr Zucker ersetzen, der Geschmack ist dann aber weniger tief als mit Tamarinde."},{"q":"Warum werden die Nudeln eingeweicht statt gekocht?","a":"Sie garen im Wok mit der Sauce fertig. Würde man sie vorher kochen, wären sie zu weich und würden beim Braten brechen."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"4c797e69-22fd-5498-ac95-1e1f28d7518f","recipe_group_id":"dfcbd159-5bb3-4f73-af00-8afb13e5c9b1","language":"en","slug":"shrimp-pad-thai","public_path":"/en/shrimp-pad-thai","source_url":null,"title":"Shrimp Pad Thai","excerpt":"Homemade pad thai with rice noodles, shrimp, egg and tamarind sauce, stir-fried in a wok in 10 minutes. Serves 4.","summary":"Pad thai is a Thai stir-fry of flat rice noodles with shrimp, egg, bean sprouts and a sweet-and-sour sauce of tamarind, fish sauce and palm sugar. The noodles soak for 30 minutes in lukewarm water; they are not boiled.\n\nStir-frying in a hot wok takes about 10 minutes. Serve with roasted peanuts, lime and chili flakes. It serves 4.","category":"Main dishes","difficulty":"Medium","course":"Main dish","cuisine":"Thai","prep_time_minutes":45,"cook_time_minutes":10,"total_time_minutes":55,"servings":4,"keywords":["pad thai","shrimp pad thai","pad thai recipe","homemade pad thai","stir-fried rice noodles","tamarind sauce","Thai food"],"ingredients":[{"name":"flat rice noodles (5 mm)","amount":"200","unit":"g","group":"For the stir-fry"},{"name":"shrimp, peeled","amount":"250","unit":"g","group":"For the stir-fry"},{"name":"garlic, minced","amount":"3","unit":"cloves","group":"For the stir-fry"},{"name":"shallot, minced","amount":"1","unit":"piece","group":"For the stir-fry"},{"name":"vegetable oil","amount":"45","unit":"ml","group":"For the stir-fry"},{"name":"eggs","amount":"2","unit":"piece","group":"For the stir-fry"},{"name":"bean sprouts","amount":"150","unit":"g","group":"For the stir-fry"},{"name":"scallions, cut in 4 cm pieces","amount":"4","unit":"piece","group":"For the stir-fry"},{"name":"tamarind paste","amount":"3","unit":"tablespoon","group":"For the sauce"},{"name":"fish sauce","amount":"45","unit":"ml","group":"For the sauce"},{"name":"palm sugar (or brown sugar)","amount":"2","unit":"tablespoon","group":"For the sauce"},{"name":"water","amount":"45","unit":"ml","group":"For the sauce"},{"name":"roasted peanuts, chopped","amount":"40","unit":"g","group":"To serve"},{"name":"lime, in wedges","amount":"1","unit":"piece","group":"To serve"},{"name":"chili flakes","amount":"0.5","unit":"teaspoon","group":"To serve"}],"steps":[{"title":"Soak the noodles","content":"Soak 200 g flat rice noodles in lukewarm tap water for 30 minutes, until they bend without breaking. Drain them.","image_url":"/recetas/pad-thai-tailandia/paso-01.webp","image_alt":"Shrimp Pad Thai: Soak the noodles"},{"title":"Make the sauce","content":"Mix 3 tablespoons tamarind paste, 45 ml fish sauce, 2 tablespoons palm sugar and 45 ml water until the sugar dissolves.","image_url":"/recetas/pad-thai-tailandia/paso-02.webp","image_alt":"Shrimp Pad Thai: Make the sauce"},{"title":"Prep the ingredients","content":"Peel 250 g shrimp. Mince 3 garlic cloves and 1 shallot, cut 4 scallions into 4 cm pieces and chop 40 g roasted peanuts.","image_url":"/recetas/pad-thai-tailandia/paso-03.webp","image_alt":"Shrimp Pad Thai: Prep the ingredients"},{"title":"Stir-fry the shrimp","content":"Heat a wok over high heat with 45 ml oil. Stir-fry the shallot and garlic for 20 seconds, add the shrimp and cook 1 ½ minutes, until pink. Push them to one side.","image_url":"/recetas/pad-thai-tailandia/paso-04.webp","image_alt":"Shrimp Pad Thai: Stir-fry the shrimp"},{"title":"Cook the egg","content":"In the empty space in the wok, scramble 2 eggs for 30 seconds.","image_url":"/recetas/pad-thai-tailandia/paso-05.webp","image_alt":"Shrimp Pad Thai: Cook the egg"},{"title":"Add noodles and sauce","content":"Add the drained noodles and the sauce. Stir-fry 2 to 3 minutes, until they absorb the sauce and are tender. If they dry out, add a splash of water.","image_url":"/recetas/pad-thai-tailandia/paso-06.webp","image_alt":"Shrimp Pad Thai: Add noodles and sauce"},{"title":"Add the sprouts","content":"Off the heat, toss in half of 150 g bean sprouts and the scallions for 30 seconds.","image_url":"/recetas/pad-thai-tailandia/paso-07.webp","image_alt":"Shrimp Pad Thai: Add the sprouts"},{"title":"Serve","content":"Serve with the peanuts, the remaining sprouts, lime wedges and ½ teaspoon chili flakes.","image_url":"/recetas/pad-thai-tailandia/paso-08.webp","image_alt":"Shrimp Pad Thai: Serve"}],"image_url":"/recetas/pad-thai-tailandia/portada.webp","gallery":[{"url":"/recetas/pad-thai-tailandia/portada.webp","alt":"Shrimp Pad Thai"}],"notes":"The preparation time includes 30 minutes of soaking the noodles. Have everything ready before you light the stove: cooking is very fast. If your wok is small, cook in two batches so the noodles fry instead of steaming. Contains peanuts, shellfish, fish and egg.","nutrition":{"calories":500,"protein_g":22.5,"carbs_g":61,"fat_g":18.4,"sodium_mg":1192,"serving_size":"1 serving (1/4 of the recipe)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Sum of nutrients per 100 g multiplied by the ingredient weights and divided by 4 servings. It uses 200 g dry rice noodles, 250 g shrimp, 100 g egg, 48 g tamarind paste, 54 g fish sauce (45 ml), 25 g sugar, 41 g oil (45 ml), 9 g garlic, 25 g shallot, 150 g bean sprouts, 40 g scallion and 40 g peanuts.","note":"Estimate per serving. Lime and chili flakes are not counted. Tamarind paste and palm sugar are calculated with reference values (raw tamarind and brown sugar). Sodium comes mostly from the fish sauce."},"seo":{"title":"Shrimp pad thai at home in 10 minutes | Manual de Cocina","description":"Homemade shrimp pad thai with rice noodles, egg and tamarind sauce, stir-fried in a wok in 10 minutes. Step-by-step recipe for 4 servings.","image_variants":["/recetas/pad-thai-tailandia/portada-1x1.webp","/recetas/pad-thai-tailandia/portada-4x3.webp","/recetas/pad-thai-tailandia/portada-16x9.webp"],"faq":[{"q":"What noodles do you use for pad thai?","a":"Flat rice noodles about 5 mm wide. They are soaked in lukewarm water for about 30 minutes and not boiled."},{"q":"Can you make pad thai without tamarind paste?","a":"You can replace it with lime juice and a little more sugar, but the flavor will be less deep than with tamarind."},{"q":"Why soak the noodles instead of boiling them?","a":"They finish softening in the wok with the sauce. If you boil them first, they overcook and break when stir-fried."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"b2773c24-9f13-5652-8a9f-b3e5f40e6f7f","recipe_group_id":"dfcbd159-5bb3-4f73-af00-8afb13e5c9b1","language":"fr","slug":"pad-thai-crevettes","public_path":"/fr/pad-thai-crevettes","source_url":null,"title":"Pad thaï aux crevettes","excerpt":"Pad thaï maison aux nouilles de riz, crevettes, œuf et sauce au tamarin, sauté au wok en 10 minutes. Pour 4 personnes.","summary":"Le pad thaï est un sauté thaïlandais de nouilles de riz plates aux crevettes, à l’œuf et aux germes de soja, avec une sauce aigre-douce au tamarin, sauce de poisson et sucre de palme. Les nouilles trempent 30 minutes dans de l’eau tiède, sans être bouillies.\n\nLa cuisson au wok à feu vif dure environ 10 minutes. On sert avec des cacahuètes grillées, du citron vert et des flocons de piment. Pour 4 personnes.","category":"Plats principaux","difficulty":"Moyenne","course":"Plat principal","cuisine":"Thaïlandaise","prep_time_minutes":45,"cook_time_minutes":10,"total_time_minutes":55,"servings":4,"keywords":["pad thaï","pad thaï aux crevettes","recette de pad thaï","pad thaï maison","nouilles de riz sautées","sauce au tamarin","cuisine thaïlandaise"],"ingredients":[{"name":"nouilles de riz plates (5 mm)","amount":"200","unit":"g","group":"Pour le sauté"},{"name":"crevettes décortiquées","amount":"250","unit":"g","group":"Pour le sauté"},{"name":"ail, haché","amount":"3","unit":"gousses","group":"Pour le sauté"},{"name":"échalote, hachée","amount":"1","unit":"pièce","group":"Pour le sauté"},{"name":"huile végétale","amount":"45","unit":"ml","group":"Pour le sauté"},{"name":"œufs","amount":"2","unit":"pièce","group":"Pour le sauté"},{"name":"germes de soja","amount":"150","unit":"g","group":"Pour le sauté"},{"name":"ciboules, en tronçons de 4 cm","amount":"4","unit":"pièce","group":"Pour le sauté"},{"name":"pâte de tamarin","amount":"3","unit":"cuillère à soupe","group":"Pour la sauce"},{"name":"sauce de poisson","amount":"45","unit":"ml","group":"Pour la sauce"},{"name":"sucre de palme (ou sucre roux)","amount":"2","unit":"cuillère à soupe","group":"Pour la sauce"},{"name":"eau","amount":"45","unit":"ml","group":"Pour la sauce"},{"name":"cacahuètes grillées, concassées","amount":"40","unit":"g","group":"Pour servir"},{"name":"citron vert, en quartiers","amount":"1","unit":"pièce","group":"Pour servir"},{"name":"flocons de piment","amount":"0.5","unit":"cuillère à café","group":"Pour servir"}],"steps":[{"title":"Faire tremper les nouilles","content":"Faire tremper 200 g de nouilles de riz plates dans de l’eau du robinet tiède pendant 30 minutes, jusqu’à ce qu’elles plient sans casser. Les égoutter.","image_url":"/recetas/pad-thai-tailandia/paso-01.webp","image_alt":"Pad thaï aux crevettes: Faire tremper les nouilles"},{"title":"Préparer la sauce","content":"Mélanger 3 cuillères à soupe de pâte de tamarin, 45 ml de sauce de poisson, 2 cuillères à soupe de sucre de palme et 45 ml d’eau jusqu’à dissolution du sucre.","image_url":"/recetas/pad-thai-tailandia/paso-02.webp","image_alt":"Pad thaï aux crevettes: Préparer la sauce"},{"title":"Préparer les ingrédients","content":"Décortiquer 250 g de crevettes. Hacher 3 gousses d’ail et 1 échalote, couper 4 ciboules en tronçons de 4 cm et concasser 40 g de cacahuètes grillées.","image_url":"/recetas/pad-thai-tailandia/paso-03.webp","image_alt":"Pad thaï aux crevettes: Préparer les ingrédients"},{"title":"Saisir les crevettes","content":"Chauffer un wok à feu vif avec 45 ml d’huile. Faire sauter l’échalote et l’ail 20 secondes, ajouter les crevettes et les cuire 1 minute 30, jusqu’à ce qu’elles soient roses. Les pousser sur le côté.","image_url":"/recetas/pad-thai-tailandia/paso-04.webp","image_alt":"Pad thaï aux crevettes: Saisir les crevettes"},{"title":"Cuire l’œuf","content":"Dans l’espace libre du wok, brouiller 2 œufs pendant 30 secondes.","image_url":"/recetas/pad-thai-tailandia/paso-05.webp","image_alt":"Pad thaï aux crevettes: Cuire l’œuf"},{"title":"Ajouter nouilles et sauce","content":"Ajouter les nouilles égouttées et la sauce. Faire sauter 2 à 3 minutes, jusqu’à ce qu’elles absorbent la sauce et soient tendres. Si elles sèchent, ajouter un filet d’eau.","image_url":"/recetas/pad-thai-tailandia/paso-06.webp","image_alt":"Pad thaï aux crevettes: Ajouter nouilles et sauce"},{"title":"Ajouter les germes","content":"Hors du feu, mélanger pendant 30 secondes la moitié de 150 g de germes de soja et les ciboules.","image_url":"/recetas/pad-thai-tailandia/paso-07.webp","image_alt":"Pad thaï aux crevettes: Ajouter les germes"},{"title":"Servir","content":"Servir avec les cacahuètes, le reste des germes, des quartiers de citron vert et ½ cuillère à café de flocons de piment.","image_url":"/recetas/pad-thai-tailandia/paso-08.webp","image_alt":"Pad thaï aux crevettes: Servir"}],"image_url":"/recetas/pad-thai-tailandia/portada.webp","gallery":[{"url":"/recetas/pad-thai-tailandia/portada.webp","alt":"Pad thaï aux crevettes"}],"notes":"Le temps de préparation inclut 30 minutes de trempage des nouilles. Préparez tous les ingrédients avant d’allumer le feu : la cuisson est très rapide. Si votre wok est petit, cuisez en deux fois pour que les nouilles sautent au lieu de cuire à la vapeur. Contient cacahuètes, crustacés, poisson et œuf.","nutrition":{"calories":500,"protein_g":22.5,"carbs_g":61,"fat_g":18.4,"sodium_mg":1192,"serving_size":"1 portion (1/4 de la recette)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somme des nutriments pour 100 g multipliés par le poids des ingrédients et divisés par 4 portions. On utilise 200 g de nouilles de riz sèches, 250 g de crevettes, 100 g d’œuf, 48 g de pâte de tamarin, 54 g de sauce de poisson (45 ml), 25 g de sucre, 41 g d’huile (45 ml), 9 g d’ail, 25 g d’échalote, 150 g de germes de soja, 40 g de ciboule et 40 g de cacahuètes.","note":"Estimation par portion. Le citron vert et les flocons de piment ne sont pas comptés. La pâte de tamarin et le sucre de palme sont calculés avec des valeurs de référence (tamarin cru et sucre roux). Le sodium vient surtout de la sauce de poisson."},"seo":{"title":"Pad thaï aux crevettes maison en 10 minutes | Manual de Cocina","description":"Pad thaï maison aux nouilles de riz, crevettes, œuf et sauce au tamarin, sauté au wok en 10 minutes. Recette pas à pas pour 4 personnes.","image_variants":["/recetas/pad-thai-tailandia/portada-1x1.webp","/recetas/pad-thai-tailandia/portada-4x3.webp","/recetas/pad-thai-tailandia/portada-16x9.webp"],"faq":[{"q":"Quelles nouilles utiliser pour le pad thaï ?","a":"Des nouilles de riz plates d’environ 5 mm de large. On les fait tremper dans de l’eau tiède environ 30 minutes, sans les bouillir."},{"q":"Peut-on faire du pad thaï sans pâte de tamarin ?","a":"On peut la remplacer par du jus de citron vert avec un peu plus de sucre, mais le goût sera moins profond qu’avec le tamarin."},{"q":"Pourquoi tremper les nouilles au lieu de les bouillir ?","a":"Elles finissent de ramollir dans le wok avec la sauce. Bouillies avant, elles seraient trop cuites et se casseraient à la poêle."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"934f2fcf-040f-5e03-ba36-ba02140d3013","recipe_group_id":"dfcbd159-5bb3-4f73-af00-8afb13e5c9b1","language":"it","slug":"pad-thai-con-gamberi","public_path":"/it/pad-thai-con-gamberi","source_url":null,"title":"Pad Thai con gamberi","excerpt":"Pad Thai fatto in casa con noodles di riso, gamberi, uovo e salsa di tamarindo, saltato nel wok in 10 minuti. Per 4 porzioni.","summary":"Il pad thai è un saltato thailandese di noodles di riso piatti con gamberi, uovo, germogli di soia e una salsa agrodolce di tamarindo, salsa di pesce e zucchero di palma. I noodles restano 30 minuti in ammollo in acqua tiepida, senza essere bolliti.\n\nLa cottura nel wok a fuoco vivace dura circa 10 minuti. Si serve con arachidi tostate, lime e peperoncino in scaglie. Per 4 porzioni.","category":"Secondi piatti","difficulty":"Media","course":"Piatto principale","cuisine":"Thailandese","prep_time_minutes":45,"cook_time_minutes":10,"total_time_minutes":55,"servings":4,"keywords":["pad thai","pad thai con gamberi","ricetta pad thai","pad thai fatto in casa","noodles di riso saltati","salsa di tamarindo","cucina thailandese"],"ingredients":[{"name":"noodles di riso piatti (5 mm)","amount":"200","unit":"g","group":"Per il saltato"},{"name":"gamberi sgusciati","amount":"250","unit":"g","group":"Per il saltato"},{"name":"aglio, tritato","amount":"3","unit":"spicchi","group":"Per il saltato"},{"name":"scalogno, tritato","amount":"1","unit":"unità","group":"Per il saltato"},{"name":"olio vegetale","amount":"45","unit":"ml","group":"Per il saltato"},{"name":"uova","amount":"2","unit":"unità","group":"Per il saltato"},{"name":"germogli di soia","amount":"150","unit":"g","group":"Per il saltato"},{"name":"cipollotti, a pezzi da 4 cm","amount":"4","unit":"unità","group":"Per il saltato"},{"name":"pasta di tamarindo","amount":"3","unit":"cucchiaio","group":"Per la salsa"},{"name":"salsa di pesce","amount":"45","unit":"ml","group":"Per la salsa"},{"name":"zucchero di palma (o zucchero di canna)","amount":"2","unit":"cucchiaio","group":"Per la salsa"},{"name":"acqua","amount":"45","unit":"ml","group":"Per la salsa"},{"name":"arachidi tostate, tritate","amount":"40","unit":"g","group":"Per servire"},{"name":"lime, a spicchi","amount":"1","unit":"unità","group":"Per servire"},{"name":"peperoncino in scaglie","amount":"0.5","unit":"cucchiaino","group":"Per servire"}],"steps":[{"title":"Metti in ammollo i noodles","content":"Metti in ammollo 200 g di noodles di riso piatti in acqua del rubinetto tiepida per 30 minuti, finché si piegano senza spezzarsi. Scolali.","image_url":"/recetas/pad-thai-tailandia/paso-01.webp","image_alt":"Pad Thai con gamberi: Metti in ammollo i noodles"},{"title":"Prepara la salsa","content":"Mescola 3 cucchiai di pasta di tamarindo, 45 ml di salsa di pesce, 2 cucchiai di zucchero di palma e 45 ml di acqua finché lo zucchero si scioglie.","image_url":"/recetas/pad-thai-tailandia/paso-02.webp","image_alt":"Pad Thai con gamberi: Prepara la salsa"},{"title":"Prepara gli ingredienti","content":"Sguscia 250 g di gamberi. Trita 3 spicchi d’aglio e 1 scalogno, taglia 4 cipollotti a pezzi da 4 cm e trita grossolanamente 40 g di arachidi tostate.","image_url":"/recetas/pad-thai-tailandia/paso-03.webp","image_alt":"Pad Thai con gamberi: Prepara gli ingredienti"},{"title":"Salta i gamberi","content":"Scalda un wok a fuoco vivace con 45 ml di olio. Salta lo scalogno e l’aglio per 20 secondi, aggiungi i gamberi e cuocili 1 minuto e mezzo, finché sono rosa. Spostali da un lato.","image_url":"/recetas/pad-thai-tailandia/paso-04.webp","image_alt":"Pad Thai con gamberi: Salta i gamberi"},{"title":"Cuoci l’uovo","content":"Nello spazio libero del wok, strapazza 2 uova per 30 secondi.","image_url":"/recetas/pad-thai-tailandia/paso-05.webp","image_alt":"Pad Thai con gamberi: Cuoci l’uovo"},{"title":"Aggiungi noodles e salsa","content":"Aggiungi i noodles scolati e la salsa. Salta da 2 a 3 minuti, finché assorbono la salsa e sono teneri. Se si asciugano, aggiungi un goccio d’acqua.","image_url":"/recetas/pad-thai-tailandia/paso-06.webp","image_alt":"Pad Thai con gamberi: Aggiungi noodles e salsa"},{"title":"Aggiungi i germogli","content":"Fuori dal fuoco, mescola per 30 secondi metà di 150 g di germogli di soia e i cipollotti.","image_url":"/recetas/pad-thai-tailandia/paso-07.webp","image_alt":"Pad Thai con gamberi: Aggiungi i germogli"},{"title":"Servi","content":"Servi con le arachidi, i germogli rimasti, spicchi di lime e ½ cucchiaino di peperoncino in scaglie.","image_url":"/recetas/pad-thai-tailandia/paso-08.webp","image_alt":"Pad Thai con gamberi: Servi"}],"image_url":"/recetas/pad-thai-tailandia/portada.webp","gallery":[{"url":"/recetas/pad-thai-tailandia/portada.webp","alt":"Pad Thai con gamberi"}],"notes":"Il tempo di preparazione include 30 minuti di ammollo dei noodles. Prepara tutti gli ingredienti prima di accendere il fuoco: la cottura è molto veloce. Se il wok è piccolo, cuoci in due volte, così i noodles si saltano invece di cuocere al vapore. Contiene arachidi, crostacei, pesce e uovo.","nutrition":{"calories":500,"protein_g":22.5,"carbs_g":61,"fat_g":18.4,"sodium_mg":1192,"serving_size":"1 porzione (1/4 della ricetta)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somma dei nutrienti per 100 g moltiplicati per il peso degli ingredienti e divisi per 4 porzioni. Si usano 200 g di noodles di riso secchi, 250 g di gamberi, 100 g di uovo, 48 g di pasta di tamarindo, 54 g di salsa di pesce (45 ml), 25 g di zucchero, 41 g di olio (45 ml), 9 g di aglio, 25 g di scalogno, 150 g di germogli di soia, 40 g di cipollotto e 40 g di arachidi.","note":"Stima per porzione. Lime e peperoncino in scaglie non sono conteggiati. Pasta di tamarindo e zucchero di palma sono calcolati con valori di riferimento (tamarindo crudo e zucchero di canna). Il sodio proviene soprattutto dalla salsa di pesce."},"seo":{"title":"Pad Thai con gamberi fatto in casa in 10 minuti | Manual de Cocina","description":"Pad Thai fatto in casa con noodles di riso, gamberi, uovo e salsa di tamarindo, saltato nel wok in 10 minuti. Passo passo per 4 porzioni.","image_variants":["/recetas/pad-thai-tailandia/portada-1x1.webp","/recetas/pad-thai-tailandia/portada-4x3.webp","/recetas/pad-thai-tailandia/portada-16x9.webp"],"faq":[{"q":"Quali noodles si usano per il pad thai?","a":"Noodles di riso piatti larghi circa 5 mm. Si mettono in ammollo in acqua tiepida per circa 30 minuti e non si bollono."},{"q":"Si può fare il pad thai senza pasta di tamarindo?","a":"Si può sostituire con succo di lime e un po’ più di zucchero, ma il sapore sarà meno profondo che con il tamarindo."},{"q":"Perché i noodles si mettono in ammollo invece di bollirli?","a":"Finiscono di ammorbidirsi nel wok con la salsa. Se li bolli prima, si stracuociono e si spezzano quando li salti."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"de5c826c-a558-5dd4-9040-8f6a52ff2263","recipe_group_id":"dfcbd159-5bb3-4f73-af00-8afb13e5c9b1","language":"ja","slug":"パッタイ","public_path":"/ja/パッタイ","source_url":null,"title":"海老のパッタイ","excerpt":"米粉の平麺、エビ、卵、タマリンドソースで作る手作りパッタイ。中華鍋で10分炒めて完成。4人分。","summary":"パッタイは、平たいライスヌードルにエビ、卵、もやしを合わせ、タマリンド、ナンプラー、パームシュガーの甘酸っぱいソースで炒めるタイの炒め麺です。麺はゆでずに、ぬるま湯で30分戻します。\n\n強火の中華鍋で炒める時間は約10分。ローストピーナッツ、ライム、唐辛子フレークを添えて食べます。4人分です。","category":"主菜","difficulty":"普通","course":"主菜","cuisine":"タイ料理","prep_time_minutes":45,"cook_time_minutes":10,"total_time_minutes":55,"servings":4,"keywords":["パッタイ","海老のパッタイ","パッタイ レシピ","手作りパッタイ","ライスヌードル 炒め","タマリンドソース","タイ料理"],"ingredients":[{"name":"平たいライスヌードル（5mm幅）","amount":"200","unit":"g","group":"炒め用"},{"name":"エビ、殻をむく","amount":"250","unit":"g","group":"炒め用"},{"name":"にんにく、みじん切り","amount":"3","unit":"かけ","group":"炒め用"},{"name":"エシャロット、みじん切り","amount":"1","unit":"個","group":"炒め用"},{"name":"植物油","amount":"45","unit":"ml","group":"炒め用"},{"name":"卵","amount":"2","unit":"個","group":"炒め用"},{"name":"もやし","amount":"150","unit":"g","group":"炒め用"},{"name":"ねぎ、4cmに切る","amount":"4","unit":"本","group":"炒め用"},{"name":"タマリンドペースト","amount":"3","unit":"大さじ","group":"ソース用"},{"name":"ナンプラー","amount":"45","unit":"ml","group":"ソース用"},{"name":"パームシュガー（または黒砂糖）","amount":"2","unit":"大さじ","group":"ソース用"},{"name":"水","amount":"45","unit":"ml","group":"ソース用"},{"name":"ローストピーナッツ、粗く刻む","amount":"40","unit":"g","group":"仕上げ用"},{"name":"ライム、くし切り","amount":"1","unit":"個","group":"仕上げ用"},{"name":"唐辛子フレーク","amount":"0.5","unit":"小さじ","group":"仕上げ用"}],"steps":[{"title":"麺を戻す","content":"平たいライスヌードル200gを、ぬるま湯に30分つけます。折れずに曲がるくらいになったら、水気を切ります。","image_url":"/recetas/pad-thai-tailandia/paso-01.webp","image_alt":"海老のパッタイ: 麺を戻す"},{"title":"ソースを作る","content":"タマリンドペースト大さじ3、ナンプラー45ml、パームシュガー大さじ2、水45mlを、砂糖が溶けるまで混ぜます。","image_url":"/recetas/pad-thai-tailandia/paso-02.webp","image_alt":"海老のパッタイ: ソースを作る"},{"title":"材料を準備する","content":"エビ250gの殻をむきます。にんにく3かけとエシャロット1個をみじん切りにし、ねぎ4本を4cmに切り、ローストピーナッツ40gを粗く刻みます。","image_url":"/recetas/pad-thai-tailandia/paso-03.webp","image_alt":"海老のパッタイ: 材料を準備する"},{"title":"エビを炒める","content":"中華鍋を強火で熱し、油45mlを入れます。エシャロットとにんにくを20秒炒め、エビを加えて1分30秒、ピンク色になるまで炒めます。鍋の端に寄せます。","image_url":"/recetas/pad-thai-tailandia/paso-04.webp","image_alt":"海老のパッタイ: エビを炒める"},{"title":"卵を焼く","content":"あいた場所で、卵2個を30秒かき混ぜながら炒めます。","image_url":"/recetas/pad-thai-tailandia/paso-05.webp","image_alt":"海老のパッタイ: 卵を焼く"},{"title":"麺とソースを加える","content":"水気を切った麺とソースを加え、2〜3分炒めます。麺がソースを吸ってやわらかくなればできあがりです。乾くようなら水を少し足します。","image_url":"/recetas/pad-thai-tailandia/paso-06.webp","image_alt":"海老のパッタイ: 麺とソースを加える"},{"title":"もやしを加える","content":"火を止めて、もやし150gの半量とねぎを加え、30秒混ぜます。","image_url":"/recetas/pad-thai-tailandia/paso-07.webp","image_alt":"海老のパッタイ: もやしを加える"},{"title":"盛り付ける","content":"ピーナッツ、残りのもやし、くし切りのライム、唐辛子フレーク小さじ1/2を添えて盛り付けます。","image_url":"/recetas/pad-thai-tailandia/paso-08.webp","image_alt":"海老のパッタイ: 盛り付ける"}],"image_url":"/recetas/pad-thai-tailandia/portada.webp","gallery":[{"url":"/recetas/pad-thai-tailandia/portada.webp","alt":"海老のパッタイ"}],"notes":"調理時間には麺を戻す30分を含みます。調理はとても速いので、火をつける前にすべての材料を準備しておいてください。鍋が小さいときは、麺が蒸し焼きにならないよう2回に分けて炒めます。ピーナッツ、甲殻類、魚、卵を含みます。","nutrition":{"calories":500,"protein_g":22.5,"carbs_g":61,"fat_g":18.4,"sodium_mg":1192,"serving_size":"1人分（レシピの1/4）","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"100gあたりの栄養素に材料の重量を掛け、4人分で割って合計しています。乾燥ライスヌードル200g、エビ250g、卵100g、タマリンドペースト48g、ナンプラー54g（45ml）、砂糖25g、油41g（45ml）、にんにく9g、エシャロット25g、もやし150g、ねぎ40g、ピーナッツ40gを使用しています。","note":"1人分の目安です。ライムと唐辛子フレークは含みません。タマリンドペーストとパームシュガーは参考値（生のタマリンドと黒砂糖）で計算しています。ナトリウムは主にナンプラーに由来します。"},"seo":{"title":"海老のパッタイの作り方｜10分で作る手作りパッタイ | Manual de Cocina","description":"ライスヌードル、エビ、卵、タマリンドソースで作る手作りパッタイ。中華鍋で10分炒めて完成。4人分の手順を写真付きで解説します。","image_variants":["/recetas/pad-thai-tailandia/portada-1x1.webp","/recetas/pad-thai-tailandia/portada-4x3.webp","/recetas/pad-thai-tailandia/portada-16x9.webp"],"faq":[{"q":"パッタイにはどんな麺を使いますか？","a":"幅5mmほどの平たいライスヌードルを使います。ゆでずに、ぬるま湯で約30分戻します。"},{"q":"タマリンドペーストなしでパッタイは作れますか？","a":"ライム汁と少し多めの砂糖で代用できますが、タマリンドほどの深みは出ません。"},{"q":"なぜ麺をゆでずに戻すのですか？","a":"麺は鍋でソースと一緒に炒める間にやわらかくなります。先にゆでると、炒めるときに煮えすぎて切れてしまいます。"}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"5be5d12c-e67f-579c-aad9-21bd6fac5b2d","recipe_group_id":"dfcbd159-5bb3-4f73-af00-8afb13e5c9b1","language":"pt","slug":"pad-thai-camarao","public_path":"/pt/pad-thai-camarao","source_url":null,"title":"Pad Thai de camarão","excerpt":"Pad Thai caseiro com macarrão de arroz, camarão, ovo e molho de tamarindo, salteado no wok em 10 minutos. Rende 4 porções.","summary":"O pad thai é um salteado tailandês de macarrão de arroz chato com camarão, ovo, brotos de feijão e um molho agridoce de tamarindo, molho de peixe e açúcar de palma. O macarrão fica 30 minutos de molho em água morna, sem ser fervido.\n\nO salteado no wok em fogo alto leva cerca de 10 minutos. Serve-se com amendoim torrado, limão e flocos de pimenta. Rende 4 porções.","category":"Pratos principais","difficulty":"Média","course":"Prato principal","cuisine":"Tailandesa","prep_time_minutes":45,"cook_time_minutes":10,"total_time_minutes":55,"servings":4,"keywords":["pad thai","pad thai de camarão","receita de pad thai","pad thai caseiro","macarrão de arroz salteado","molho de tamarindo","comida tailandesa"],"ingredients":[{"name":"macarrão de arroz chato (5 mm)","amount":"200","unit":"g","group":"Para o salteado"},{"name":"camarões descascados","amount":"250","unit":"g","group":"Para o salteado"},{"name":"alho, picado","amount":"3","unit":"dentes","group":"Para o salteado"},{"name":"chalota, picada","amount":"1","unit":"unidade","group":"Para o salteado"},{"name":"óleo vegetal","amount":"45","unit":"ml","group":"Para o salteado"},{"name":"ovos","amount":"2","unit":"unidade","group":"Para o salteado"},{"name":"brotos de feijão","amount":"150","unit":"g","group":"Para o salteado"},{"name":"cebolinhas, em pedaços de 4 cm","amount":"4","unit":"unidade","group":"Para o salteado"},{"name":"pasta de tamarindo","amount":"3","unit":"colher de sopa","group":"Para o molho"},{"name":"molho de peixe","amount":"45","unit":"ml","group":"Para o molho"},{"name":"açúcar de palma (ou açúcar mascavo)","amount":"2","unit":"colher de sopa","group":"Para o molho"},{"name":"água","amount":"45","unit":"ml","group":"Para o molho"},{"name":"amendoim torrado, picado","amount":"40","unit":"g","group":"Para servir"},{"name":"limão, em gomos","amount":"1","unit":"unidade","group":"Para servir"},{"name":"flocos de pimenta","amount":"0.5","unit":"colher de chá","group":"Para servir"}],"steps":[{"title":"Deixe o macarrão de molho","content":"Deixe 200 g de macarrão de arroz chato de molho em água da torneira morna por 30 minutos, até dobrar sem quebrar. Escorra.","image_url":"/recetas/pad-thai-tailandia/paso-01.webp","image_alt":"Pad Thai de camarão: Deixe o macarrão de molho"},{"title":"Prepare o molho","content":"Misture 3 colheres de sopa de pasta de tamarindo, 45 ml de molho de peixe, 2 colheres de sopa de açúcar de palma e 45 ml de água até o açúcar dissolver.","image_url":"/recetas/pad-thai-tailandia/paso-02.webp","image_alt":"Pad Thai de camarão: Prepare o molho"},{"title":"Prepare os ingredientes","content":"Descasque 250 g de camarões. Pique 3 dentes de alho e 1 chalota, corte 4 cebolinhas em pedaços de 4 cm e pique 40 g de amendoim torrado.","image_url":"/recetas/pad-thai-tailandia/paso-03.webp","image_alt":"Pad Thai de camarão: Prepare os ingredientes"},{"title":"Salteie os camarões","content":"Aqueça um wok em fogo alto com 45 ml de óleo. Salteie a chalota e o alho por 20 segundos, junte os camarões e cozinhe 1 minuto e meio, até ficarem rosados. Empurre para um lado.","image_url":"/recetas/pad-thai-tailandia/paso-04.webp","image_alt":"Pad Thai de camarão: Salteie os camarões"},{"title":"Cozinhe o ovo","content":"No espaço livre do wok, mexa 2 ovos por 30 segundos.","image_url":"/recetas/pad-thai-tailandia/paso-05.webp","image_alt":"Pad Thai de camarão: Cozinhe o ovo"},{"title":"Junte macarrão e molho","content":"Adicione o macarrão escorrido e o molho. Salteie de 2 a 3 minutos, até absorver o molho e ficar macio. Se secar, junte um fio de água.","image_url":"/recetas/pad-thai-tailandia/paso-06.webp","image_alt":"Pad Thai de camarão: Junte macarrão e molho"},{"title":"Junte os brotos","content":"Fora do fogo, misture por 30 segundos metade de 150 g de brotos de feijão e as cebolinhas.","image_url":"/recetas/pad-thai-tailandia/paso-07.webp","image_alt":"Pad Thai de camarão: Junte os brotos"},{"title":"Sirva","content":"Sirva com o amendoim, o restante dos brotos, gomos de limão e ½ colher de chá de flocos de pimenta.","image_url":"/recetas/pad-thai-tailandia/paso-08.webp","image_alt":"Pad Thai de camarão: Sirva"}],"image_url":"/recetas/pad-thai-tailandia/portada.webp","gallery":[{"url":"/recetas/pad-thai-tailandia/portada.webp","alt":"Pad Thai de camarão"}],"notes":"O tempo de preparo inclui 30 minutos de molho do macarrão. Deixe todos os ingredientes prontos antes de ligar o fogo: o cozimento é muito rápido. Se o wok for pequeno, faça em duas levas para o macarrão saltear e não cozinhar no vapor. Contém amendoim, crustáceos, peixe e ovo.","nutrition":{"calories":500,"protein_g":22.5,"carbs_g":61,"fat_g":18.4,"sodium_mg":1192,"serving_size":"1 porção (1/4 da receita)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutrientes por 100 g multiplicados pelo peso dos ingredientes e divididos por 4 porções. Usa 200 g de macarrão de arroz seco, 250 g de camarões, 100 g de ovo, 48 g de pasta de tamarindo, 54 g de molho de peixe (45 ml), 25 g de açúcar, 41 g de óleo (45 ml), 9 g de alho, 25 g de chalota, 150 g de brotos de feijão, 40 g de cebolinha e 40 g de amendoim.","note":"Estimativa por porção. O limão e os flocos de pimenta não são contabilizados. A pasta de tamarindo e o açúcar de palma são calculados com valores de referência (tamarindo cru e açúcar mascavo). O sódio vem principalmente do molho de peixe."},"seo":{"title":"Pad Thai de camarão caseiro em 10 minutos | Manual de Cocina","description":"Pad Thai caseiro com macarrão de arroz, camarão, ovo e molho de tamarindo, salteado no wok em 10 minutos. Receita passo a passo para 4 porções.","image_variants":["/recetas/pad-thai-tailandia/portada-1x1.webp","/recetas/pad-thai-tailandia/portada-4x3.webp","/recetas/pad-thai-tailandia/portada-16x9.webp"],"faq":[{"q":"Qual macarrão se usa no pad thai?","a":"Macarrão de arroz chato com cerca de 5 mm de largura. Fica de molho em água morna por uns 30 minutos e não é fervido."},{"q":"Dá para fazer pad thai sem pasta de tamarindo?","a":"Dá para trocar por suco de limão com um pouco mais de açúcar, mas o sabor fica menos profundo do que com tamarindo."},{"q":"Por que o macarrão fica de molho em vez de ferver?","a":"Ele termina de amolecer no wok com o molho. Se for fervido antes, passa do ponto e quebra ao saltear."}]},"published":true,"editorial_status":"published","content_html":""}
]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/pad-thai-tailandia') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    '', x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;
